.wdt-custom-tabbed-timeline .wdt-tabs-container.wdt-layout-horizontal.wdt-template-bordered.ui-tabs.ui-corner-all.ui-widget.ui-widget-content {
 display: flex;
 flex-direction: column-reverse;
}

.wdt-custom-tabbed-timeline .wdt-tabs-container[class*='-template-bordered'] .wdt-tabs-list {
 justify-content: space-between;
 border-width: 1px 0 0px !important;
}

.wdt-custom-tabbed-timeline .wdt-tabs-container[class*="-template-bordered"] .wdt-tabs-list:before {
 border-color: inherit;
 border-style: inherit;
 border-width: 0;
 border-top-width: inherit;
 content: "";
 display: inline !important;
 height: auto;
 margin-top: -1px;
 position: absolute;
 left: 50%;
 top: 0;
 width: 9999px;
 transform: translateX(-50%);
}

.wdt-custom-tabbed-timeline .wdt-tabs-container[class*='-layout-horizontal'][class*='-template-bordered'] .wdt-tabs-list li .ui-tabs-anchor:before, .wdt-custom-tabbed-timeline .wdt-tabs-container[class*='-layout-horizontal'][class*='-template-bordered'] .wdt-tabs-list li .ui-tabs-anchor:after {
 height: 6px;
 margin-block: 0;
 bottom: auto;
 top: -4px;
}

.wdt-custom-stepcount-heading .wdt-heading-holder .wdt-heading-background-text-wrapper .wdt-heading-background-text {
 opacity: 1;
 -webkit-transform: translate3d(20px,0,5px);
 transform: translate3d(20px,0,5px);
 -webkit-text-shadow: 0.06em 0.03em 0.06em rgba(128, 128, 128,0.1);
 text-shadow: 0.06em 0.03em 0.06em rgb(128 128 128 / 10%);
 -webkit-text-fill-color: transparent;
 -webkit-text-stroke: 2px;
 -webkit-transition: var(--wdtBaseTransition);
 transition: var(--wdtBaseTransition);
}

.wdt-equal-splitup-list .elementor-icon-list-items {
 display: flex;
 flex-wrap: wrap;
 align-items: start;
 margin-left: -10px !important;
 margin-right: -10px !important;
 padding: 0;
}

.wdt-equal-splitup-list .elementor-icon-list-items .elementor-icon-list-item {
 display: flex;
 align-items: start;
 flex: 1 1 50%;
 margin: 0 !important;
 padding: 0 10px;
}

