[{"id":"045ffb0","elType":"section","settings":{"gap":"no"},"elements":[{"id":"e8a6104","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"99d37fa","elType":"widget","settings":{"html":"<style>

/* for section, I have used class name for column wrap and for fourth column, I have used class for center the column when responsive */


/* For - heading */
.wdt-custom-pricing-table-heading .wdt-heading-holder .wdt-heading-subtitle-wrapper {
 font-size: 42px;
 color: var(--wdtSecondaryColor);
 margin-bottom: 0;
 line-height: 1.5;
}

.wdt-custom-pricing-table-heading .wdt-heading-holder h2.wdt-heading-title-wrapper{
 font-size: 35px;
}
/* For pricing table */

.wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder{
 padding: 50px 10px;
 border-radius:var(--wdtRadius_4X);
 background-color:rgb(245, 245, 245);
}
 .wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder .wdt-pricing-table-header .wdt-content-title h5{
 font-size: 26px;
 }
 .wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder .wdt-pricing-table-media{
 margin-bottom: 35px;
 }
 .wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder .wdt-pricing-table-media .wdt-content-image a span:before{
 background: none;
 }
 .wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder .wdt-pricing-table-pricing{
 margin-bottom: 30px;
 }
 .wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder .wdt-pricing-table-pricing .wdt-pricing-table-pricing-original{
 font-size: 24px;
 margin-right: 5px;
 color: var(--wdtBodyTxtColor);
 margin-bottom: 10px;
 }
 .wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder .wdt-pricing-table-pricing .wdt-pricing-table-pricing-sale span.wdt-pricing-table-pricing-prefix{
 font-size: 50px;
 font-weight:var(--wdtFontWeight_Alt);
 color: var(--wdtHeadAltColor);
 padding-right: 0;
 }
 .wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder .wdt-pricing-table-pricing .wdt-pricing-table-pricing-sale span.wdt-pricing-table-pricing-sale-price{ 
 color: var(--wdtHeadAltColor);
 font-size: 50px;
 font-weight:var(--wdtFontWeight_Alt);
 }
 .wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder .wdt-pricing-table-pricing .wdt-pricing-table-pricing-sale span.wdt-pricing-table-pricing-suffix{
 font-size: 14px;
 color: var(--wdtHeadAltColor);
 }
 .wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder .wdt-pricing-table-features ul.wdt-pricing-table-features-list{
 display: grid;
 justify-content: center;
 text-align: left;
 }
 .elementor-element.wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder .wdt-pricing-table-features{
 margin-bottom:65px;
 }
 .elementor-element.wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder .wdt-pricing-table-features ul.wdt-pricing-table-features-list li{
 font-size: 16px;
 }
 .elementor-element.wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder .wdt-pricing-table-features ul.wdt-pricing-table-features-list li:after{
 border-top-width:0;
 }
 .elementor-element.wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder .wdt-pricing-table-features ul.wdt-pricing-table-features-list li:not(:last-child):after{
 margin-top: 0;
 }
 .wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder .wdt-pricing-table-footer .wdt-content-button{
 margin-bottom: 0;
 }
 .wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder .wdt-pricing-table-footer .wdt-content-button a{
 font-size: 16px;
 background-color: var(--wdtHeadAltColor);
 border-radius:var(--wdtRadius_3X);
 color:var(--wdtAccentTxtColor);v
 }
/* Features - include -exclude */
 .wdt-custom-pricing-table.elementor-element .wdt-pricing-table-holder .wdt-pricing-table-features-list li.wdt-pricing-table-feature-excluded .wdt-pricing-table-features-list-icon{
 color:var(--wdtPrimaryColor);
}

 .wdt-custom-pricing-table.elementor-element .wdt-pricing-table-holder .wdt-pricing-table-features-list li.wdt-pricing-table-feature-included .wdt-pricing-table-features-list-icon{
 color:var(--wdtPrimaryColor);
}

/* Hover */
.wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder:hover{
 background-color:var(--wdtSecondaryColor); 
}
.wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder:hover .wdt-pricing-table-header .wdt-content-title h5 a{
 color:var(--wdtAccentTxtColor);
}
.wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder:hover .wdt-pricing-table-pricing .wdt-pricing-table-pricing-original{
 color:var(--wdtAccentTxtColor);
}
.wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder:hover .wdt-pricing-table-pricing .wdt-pricing-table-pricing-sale span.wdt-pricing-table-pricing-prefix{
 color:var(--wdtAccentTxtColor);
}
.wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder:hover .wdt-pricing-table-pricing .wdt-pricing-table-pricing-sale span.wdt-pricing-table-pricing-sale-price{
 color:var(--wdtAccentTxtColor);
}
.wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder:hover .wdt-pricing-table-pricing .wdt-pricing-table-pricing-sale span.wdt-pricing-table-pricing-suffix{
 color:var(--wdtAccentTxtColor);
}
.elementor-element.wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder:hover .wdt-pricing-table-features ul.wdt-pricing-table-features-list li div.wdt-pricing-table-features-list-inner span.wdt-pricing-table-features-list-text{
 color:var(--wdtAccentTxtColor);
}
.wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder:hover .wdt-pricing-table-footer .wdt-content-button a{
 background-color: var(--wdtAccentTxtColor);
 color:var(--wdtHeadAltColor);
}
.wdt-custom-pricing-table .elementor-widget-container .wdt-pricing-table-holder .wdt-pricing-table-footer .wdt-content-button a:hover{
 background-color: var(--wdtPrimaryColor);
 color:var(--wdtAccentTxtColor); 
}

/* Responsiveness */

@media screen and (max-width:767px){
 .elementor-element.wdt-custom-pricing-table{
 max-width: 380px;
 margin: auto;
 }
}

